Creating a complex smart contract involves a deep understanding of blockchain technology, programming, and the specific use case for which the contract is being designed. Smart contracts are self-executing contracts with the terms of the agreement directly written into code. They run on a blockchain, which ensures that the contract is immutable and transparent.

Here's a simplified example of a complex smart contract written in Solidity, which is a programming language for writing smart contracts on the Ethereum blockchain. This example is for educational purposes and is a basic representation of a multi-party agreement with various conditions and events.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract ComplexSmartContract {
    address public partyA;
    address public partyB;
    address public partyC;
    uint public amount;
    bool public partyACanWithdraw = false;
    bool public partyBCanWithdraw = false;
    bool public partyCCanWithdraw = false;

    // Events to emit when certain actions are taken
    event PartyACanWithdraw(bool canWithdraw);
    event PartyBCanWithdraw(bool canWithdraw);
    event PartyCCanWithdraw(bool canWithdraw);
    event WithdrawalMade(address party, uint amount);

    constructor(address _partyA, address _partyB, address _partyC, uint _amount) {
        partyA = _partyA;
        partyB = _partyB;
        partyC = _partyC;
        amount = _amount;
    }

    modifier onlyPartyA() {
        require(msg.sender == partyA, "Only Party A can call this function.");
        _;
    }

    modifier onlyPartyB() {
        require(msg.sender == partyB, "Only Party B can call this function.");
        _;
    }

    modifier onlyPartyC() {
        require(msg.sender == partyC, "Only Party C can call this function.");
        _;
    }

    function setWithdrawalConditions() public onlyPartyA {
        // Set conditions for Party A to withdraw
        partyACanWithdraw = true;
        emit PartyACanWithdraw(partyACanWithdraw);
    }

    function setWithdrawalConditions() public onlyPartyB {
        // Set conditions for Party B to withdraw
        partyBCanWithdraw = true;
        emit PartyBCanWithdraw(partyBCanWithdraw);
    }

    function setWithdrawalConditions() public onlyPartyC {
        // Set conditions for Party C to withdraw
        partyCCanWithdraw = true;
        emit PartyCCanWithdraw(partyCCanWithdraw);
    }

    function makeWithdrawal() public onlyPartyA {
        require(partyACanWithdraw, "Party A cannot withdraw at this time.");
        require(address(this).balance >= amount, "Insufficient funds in contract.");
        payable(partyA).transfer(amount);
        emit WithdrawalMade(partyA, amount);
    }

    function makeWithdrawal() public onlyPartyB {
        require(partyBCanWithdraw, "Party B cannot withdraw at this time.");
        require(address(this).balance >= amount, "Insufficient funds in contract.");
        payable(partyB).transfer(amount);
        emit WithdrawalMade(partyB, amount);
    }

    function makeWithdrawal() public onlyPartyC {
        require(partyCCanWithdraw, "Party C cannot withdraw at this time.");
        require(address(this).balance >= amount, "Insufficient funds in contract.");
        payable(partyC).transfer(amount);
        emit WithdrawalMade(partyC, amount);
    }

    // Function to receive Ether. msg.data must be empty
    receive() external payable {}

    // Function to get the contract's balance
    function getBalance() public view returns (uint) {
        return address(this).balance;
    }
}
```

This contract is a basic example and does not include all the features and security measures that would be necessary for a real-world complex smart contract. In practice, smart contracts can become very intricate, with multiple functions, modifiers, events, and conditions that need to be carefully designed and tested to ensure they work as intended and are secure against potential vulnerabilities.

Before deploying any smart contract to the mainnet, it is crucial to have it audited by security professionals and to thoroughly test it in a testnet environment. Smart contracts handle real value and are immutable once deployed, so any bugs or vulnerabilities can be exploited, leading to loss of funds or other unintended consequences.

